// m68ki_cycles[0]: the base cycles of each opcode word (MAME's
// m68ki_build_opcode_table)
inline const std::array<uint8_t, 0x10000> &musashi_cycles() {
    static const std::array<uint8_t, 0x10000> t = [] {
        std::array<uint8_t, 0x10000> a{};
        for (const MusashiCycEntry &e : kMusashiCycEntries) {
            uint16_t extra = 0;
            do {
                a[uint16_t(e.match | extra)] = e.cycles;
                extra = uint16_t(((extra | e.mask) + 1) & ~e.mask);
            } while (extra);
        }
        return a;
    }();
    return t;
}

